WITH matched_keys AS (SELECT device_code FROM device_readings EXCEPT DISTINCT SELECT device_code FROM device_readings WHERE reading_ts >= '2023-08-01'), reconciled AS (SELECT s.* FROM device_readings s JOIN matched_keys k ON s.device_code = k.device_code) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, SUM(status_bits) FILTER (WHERE device_code = 'DV-02') AS dv_02_total_status_bits, STDDEV_SAMP(status_bits) AS status_bits_stddev, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count, SUM(status_bits) FILTER (WHERE device_code = 'DV-04') AS dv_04_total_status_bits FROM reconciled GROUP BY DATE_TRUNC('DAY', reading_ts) ORDER BY dv_04_total_status_bits DESC NULLS FIRST;
